/*
 * prog59_rule110.c
 *
 * Re‑implementation of the original binary “prog59_rule110”.
 *
 * Behaviour
 * ----------
 *   prog59_rule110 <binary_string> <steps>
 *
 *   * <binary_string> – a string of ‘0’ and ‘1’ characters, length 1‑60.
 *   * <steps>         – a non‑negative integer (number of additional
 *                       generations to compute).  Values >200 are capped
 *                       to 200.
 *
 *   If any of the above conditions are violated the program prints
 *
 *         INVALID_INPUT\n
 *   and exits.
 *
 *   Otherwise it prints the initial row followed by <steps> further rows
 *   of the elementary cellular automaton “Rule 110”.  Each row is a line
 *   of ‘0’/‘1’ characters terminated by a newline.
 *
 *   The implementation follows the state‑machine recovered from the
 *   obfuscated binary, but is written in clear C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEN   60          /* maximum allowed length of the binary string */
#define MAX_STEPS 200         /* maximum number of generations (capped) */

/* Rule 110 lookup table.
 * Index = (left << 2) | (center << 1) | right
 * Value = next state (0 or 1)
 *
 * 111 → 0
 * 110 → 1
 * 101 → 1
 * 100 → 0
 * 011 → 1
 * 010 → 1
 * 001 → 1
 * 000 → 0
 */
static const char RULE110[8] = {
    0, /* 000 */
    1, /* 001 */
    1, /* 010 */
    1, /* 011 */
    0, /* 100 */
    1, /* 101 */
    1, /* 110 */
    0  /* 111 */
};

static void invalid_input(void)
{
    puts("INVALID_INPUT");
}

/* Returns 1 if the string consists only of ‘0’ and ‘1’, otherwise 0. */
static int is_binary(const char *s)
{
    while (*s) {
        if (*s != '0' && *s != '1')
            return 0;
        ++s;
    }
    return 1;
}

int main(int argc, char **argv)
{
    /* ----- argument count check ----- */
    if (argc != 3) {
        invalid_input();
        return 0;
    }

    const char *init = argv[1];
    size_t len = strlen(init);

    /* ----- length checks ----- */
    if (len == 0 || len > MAX_LEN) {
        invalid_input();
        return 0;
    }

    /* ----- character check ----- */
    if (!is_binary(init)) {
        invalid_input();
        return 0;
    }

    /* ----- parse number of steps ----- */
    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0') {   /* not a pure number */
        invalid_input();
        return 0;
    }
    if (steps < 0) {          /* negative number is invalid */
        invalid_input();
        return 0;
    }
    if (steps > MAX_STEPS)    /* cap to 200 as the original binary does */
        steps = MAX_STEPS;

    /* ----- buffers for the current and next rows ----- */
    char cur[MAX_LEN + 1];
    char nxt[MAX_LEN + 1];

    memcpy(cur, init, len);
    cur[len] = '\0';

    /* ----- print the initial row ----- */
    for (size_t i = 0; i < len; ++i)
        putchar(cur[i]);
    putchar('\n');

    /* ----- generate and print the requested number of further rows ----- */
    for (long gen = 0; gen < steps; ++gen) {
        /* compute next generation according to Rule 110 */
        for (size_t i = 0; i < len; ++i) {
            int left   = (i == 0)     ? 0 : cur[i - 1] - '0';
            int center = cur[i] - '0';
            int right  = (i == len-1) ? 0 : cur[i + 1] - '0';
            int idx = (left << 2) | (center << 1) | right;
            nxt[i] = RULE110[idx] + '0';
        }
        nxt[len] = '\0';

        /* print the newly computed row */
        for (size_t i = 0; i < len; ++i)
            putchar(nxt[i]);
        putchar('\n');

        /* prepare for the next iteration */
        memcpy(cur, nxt, len + 1);
    }

    return 0;
}
